inf = 100000000000
t = int(input())

def cal(i, tr, ght, vis, st, mn):
	if vis[i] == 0:
		rtv = 0
		vis[i] = 1
		for j in tr[i]:
			if vis[j] == 0:
				rtv += cal(j, tr, ght, vis, st, min(mn, ght[i][j]))
		if i != st:
			rtv += mn
		return rtv
for rr in range(t):
	n = int(input())
	g = []
	s1 = 0
	for i in range(n):
		ip = list(map(int, input().strip().split(' ')))
		g.append(ip)
	for i in range(n):
		for j in range(n):
			s1 += g[i][j]
	for i in range(n):
		for j in range(n):
			tm = max(g[i][j], g[j][i])
			g[i][j] = tm
			g[j][i] = tm
	edj = []
	for i in range(n):
		for j in range(i + 1, n):
			if g[i][j] != 0:
				edj.append([i, j, g[i][j]])
	edj = sorted(edj, key=lambda x: x[2], reverse=True)
	edgcnt = 0
	dsu = [i for i in range(n)]
	ght = [[0] * n for i in range(n)]
	tr = [[] for i in range(n)]
	while edgcnt < n - 1:
		tm = edj[0]
		i = tm[0]
		j = tm[1]
		if dsu[i] != dsu[j]:
			mn = min(dsu[i], dsu[j])
			mx = max(dsu[i], dsu[j])
			for x in range(n):
				if dsu[x] == mx:
					dsu[x] = mn
			ght[i][j] = tm[2]
			ght[j][i] = tm[2]
			tr[i].append(j)
			tr[j].append(i)
			edgcnt += 1
		edj.remove(tm)
		if len(edj) == 0:
			break
	s2 = 0
	for i in range(n):
		vis = [0] * n
		s2 += cal(i, tr, ght, vis, i, inf)
	print(s2 - s1)
